import sys
import math

def gcd(a, b):
    return math.gcd(a, b)

def normalize_line(p1, p2):
    x1, y1 = p1
    x2, y2 = p2

    A = y1 - y2
    B = x2 - x1
    C = x1 * y2 - x2 * y1

    if A == 0 and B == 0:
        return None

    common = gcd(abs(A), gcd(abs(B), abs(C)))
    A //= common
    B //= common
    C //= common

    if A < 0 or (A == 0 and B < 0):
        A = -A
        B = -B
        C = -C

    return (A, B, C)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    points = []
    for _ in range(n):
        x = int(next(iterator))
        y = int(next(iterator))
        points.append((x, y))

    lines = set()

    for i in range(n):
        for j in range(i + 1, n):
            line = normalize_line(points[i], points[j])
            if line:
                lines.add(line)

    count = 0
    lines_list = list(lines)
    m = len(lines_list)

    for i in range(m):
        for j in range(i + 1, m):
            A1, B1, C1 = lines_list[i]
            A2, B2, C2 = lines_list[j]

            if A1 * B2 != A2 * B1:
                count += 1

    print(count)

if __name__ == "__main__":
    solve()
